examples.setupTemplate:
@State private var toasts = MonarchToastCenter()
@State private var undone = 0

private func archive() {
    toasts.show({{toast.title}}, message: {{toast.description}}, tone: {{toast.tone|tone}}, actionTitle: {{toast.action}}) {
        undone += 1
    }
}

examples.setup:
@State private var toasts = MonarchToastCenter()
@State private var undone = 0

private func archive() {
    toasts.show("Ticket archived", message: "You can undo this.", tone: .success, actionTitle: "Undo") {
        undone += 1
    }
}

examples.code:
VStack {
    MonarchButton("Archive ticket") { archive() }
}
.frame(maxWidth: .infinity, minHeight: 240)
.monarchToastHost(toasts)
.onAppear { archive() }

Text("Content")
    .frame(maxWidth: .infinity, minHeight: 240)
    .monarchToastHost(toasts, position: .top)
    .onAppear {
        toasts.show("Could not sync", message: "Check your connection.", tone: .danger, duration: .infinity)
    }

Button("Archive") {
    var undone = false
    toasts.show(
        "Ticket archived",
        actionTitle: "Undo",
        action: { undone = true },
        onDismiss: { if !undone { commitArchive() } }
    )
}
